parameters.jsCode:
const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const data = JSON.parse(raw);
return [{ json: { ...data, topic: $('Set Post Topic').item.json.topic, platform: $('Set Post Topic').item.json.platform, generated_date: new Date().toISOString().split('T')[0] } }];

const sets = $input.item.json.sets;
const formatted = sets.map(s => `${s.set_name} (${s.mix}):
${s.hashtags.join(' ')}`).join('

');
return [{ json: { formatted_sets: formatted, set_a: sets[0]?.hashtags.join(' '), set_b: sets[1]?.hashtags.join(' '), set_c: sets[2]?.hashtags.join(' '), strategy_note: $input.item.json.strategy_note, trending: $input.item.json.trending_now.join(' ') } }];

